                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="costB"
                    name="Gross cost ($B)"
                    fill={TEAL}
                    fillOpacity={0.25}
                    stroke={TEAL}
                    strokeWidth={2}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="sharePct"
                    name="Share of Part D $"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-2">
            <h3 className="text-sm font-semibold text-slate-900">
              Claims vs dollars (intensity)
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              {fmtPct(HEADLINE.glp1ClaimSharePct)} of claims ???{" "}
              {fmtPct(HEADLINE.glp1CostSharePct)} of dollars.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={INTENSITY.filter((i) => i.unit === "%").map((i) => ({
                    name: i.metric.replace("Share of Part D ", ""),
                    glp1: i.glp1,
                  }))}
                  layout="vertical"
                  margin={{ left: 8, right: 12 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} unit="%" />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={72}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar dataKey="glp1" name="GLP-1 %" radius={[0, 4, 4, 0]}>
                    <Cell fill={SKY} />
                    <Cell fill={TEAL} />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}

      {view === "brands" && (
        <div className="grid gap-4 lg:grid-cols-5">
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-3">
            <h3 className="text-sm font-semibold text-slate-900">
              Brand ladder ??? 2024 gross cost
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              Top four brands = {fmtPct(HEADLINE.top4BrandSharePct)} of the
              diabetes GLP-1 class.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={brandBars}
                  layout="vertical"
                  margin={{ left: 8, right: 16 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar dataKey="costB" name="Gross ($B)" radius={[0, 4, 4, 0]}>
                    {brandBars.map((b) => (
                      <Cell key={b.name} fill={b.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-2">
            <h3 className="text-sm font-semibold text-slate-900">
