              label: "Ozempic alone",
              value: fmtB(HEADLINE.ozempicCost2024B),
            },
            {
              label: "Cost / GLP-1 claim",
              value: fmtDollar(HEADLINE.glp1CostPerClaim),
            },
          ].map((k) => (
            <div
              key={k.label}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-2"
