              { id: "all", label: "All" },
              { id: "ozempic", label: "Ozempic" },
              { id: "mounjaro", label: "Mounjaro" },
              { id: "trulicity", label: "Trulicity" },
              { id: "rybelsus", label: "Rybelsus" },
            ]}
          />
        )}
        {view === "plans" && (
          <ToggleRow
            label="Metric"
            value={planMetric}
            onChange={setPlanMetric}
            options={[
              { id: "spend", label: "GLP-1 $ share" },
              { id: "enrollment", label: "Enrollment share" },
