                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="costB"
                    name="Gross cost ($B)"
                    fill={TEAL}
                    fillOpacity={0.25}
                    stroke={TEAL}
                    strokeWidth={2}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="sharePct"
                    name="Share of Part D $"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-2">
            <h3 className="text-sm font-semibold text-slate-900">
              Claims vs dollars (intensity)
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              {fmtPct(HEADLINE.glp1ClaimSharePct)} of claims ???{" "}
              {fmtPct(HEADLINE.glp1CostSharePct)} of dollars.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={INTENSITY.filter((i) => i.unit === "%").map((i) => ({
                    name: i.metric.replace("Share of Part D ", ""),
