                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {view === "plans" && (
        <div className="grid gap-4 lg:grid-cols-5">
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-3">
            <h3 className="text-sm font-semibold text-slate-900">
              {planMetric === "spend"
                ? "Estimated GLP-1 spend share by plan type"
                : "MedPAC enrollment share by plan type"}
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              Enrollment disclosed (MedPAC). Spend shares estimated ??? MA???PD
              carries more LIS.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={planBars}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  <Bar dataKey="value" name="Share %" radius={[4, 4, 0, 0]}>
                    {planBars.map((p) => (
                      <Cell key={p.name} fill={p.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-2">
            <h3 className="text-sm font-semibold text-slate-900">
              Est. spend mix
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              On {fmtB(HEADLINE.glp1GrossCost2024B)} class total.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={planPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={48}
                    outerRadius={88}
                    paddingAngle={2}
                  >
                    {planPie.map((p) => (
                      <Cell key={p.name} fill={p.fill} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}

      {view === "grossnet" && (
        <div className="grid gap-4 lg:grid-cols-5">
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-3">
            <h3 className="text-sm font-semibold text-slate-900">
              Gross POS vs illustrative net
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              MedPAC: diabetic-therapy rebates ???50% in 2023. Illustration only ???
              CMS cannot publish drug-level net.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={grossNetBars}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 10 }} interval={0} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <Tooltip />
                  <Bar dataKey="amount" name="$B" radius={[4, 4, 0, 0]}>
                    {grossNetBars.map((r) => (
                      <Cell key={r.name} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="rounded-xl border border-slate-200 bg-white p-4 lg:col-span-2">
            <h3 className="text-sm font-semibold text-slate-900">
              KFF broader class mix (2024)
            </h3>
            <p className="mt-1 text-xs text-slate-500">
              Share of KFF {fmtB(HEADLINE.kffGrossGlp12024B)} gross GLP-1 total.
            </p>
            <div className="mt-4 h-72">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={mixPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={90}
                    paddingAngle={1}
                  >
                    {mixPie.map((m) => (
                      <Cell key={m.name} fill={m.fill} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}

      {/* keep intensityScatter referenced for viz diversity without dead code */}
      <div className="hidden" aria-hidden>
        {intensityScatter.length}
      </div>

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

